--[=[
    @class Slot

    * 格子为容器的特定实现
    * 格子没有子节点
]=]
local Slot = {}
local Container = require(script.Parent.Container)
local Element = require(script.Parent.Container)

export type Type = typeof(Slot) & Container.Type

--[=[
    获取当前格子中的元素
    @return Element -- 元素对象
]=]
function Slot:GetElement(): Element.Type? end

return Slot
